import {createSurface} from './surface.js';
export const unitQuad=()=>[[0,0],[1,0],[1,1],[0,1]];
export function validQuad(q){if(!Array.isArray(q)||q.length!==4||q.some(v=>!Array.isArray(v)||v.length!==2||v.some(n=>!Number.isFinite(n)||n<-.75||n>1.75)))return false;let sign=0;for(let i=0;i<4;i++){const a=q[i],b=q[(i+1)%4],c=q[(i+2)%4],cross=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);if(Math.abs(cross)<.002||sign&&cross*sign<0)return false;sign=cross;}return sign>0;}
export function homography(q){const a=[];for(let i=0;i<4;i++){const [u,v]=unitQuad()[i],[x,y]=q[i];a.push([u,v,1,0,0,0,-x*u,-x*v,x],[0,0,0,u,v,1,-y*u,-y*v,y]);}for(let j=0;j<8;j++){let best=j;for(let i=j+1;i<8;i++)if(Math.abs(a[i][j])>Math.abs(a[best][j]))best=i;[a[j],a[best]]=[a[best],a[j]];const k=a[j][j];if(Math.abs(k)<1e-10)throw new Error('透视四角退化');for(let z=j;z<9;z++)a[j][z]/=k;for(let i=0;i<8;i++)if(i!==j){const n=a[i][j];for(let z=j;z<9;z++)a[i][z]-=n*a[j][z];}}return [...a.map(r=>r[8]),1];}
export function project(h,u,v){const d=h[6]*u+h[7]*v+h[8];return [(h[0]*u+h[1]*v+h[2])/d,(h[3]*u+h[4]*v+h[5])/d];}
export function inverse(m){const [a,b,c,d,e,f,g,h,i]=m;return [e*i-f*h,c*h-b*i,b*f-c*e,f*g-d*i,a*i-c*g,c*d-a*f,d*h-e*g,b*g-a*h,a*e-b*d];}
export function quadUV(q,u,v){return project(inverse(homography(q)),u,v);}
export function documentQuad(l){const a=l.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a);return (l.quad||unitQuad()).map(([u,v])=>{const x=(u-.5)*l.w,y=(v-.5)*l.h;return [l.x+x*c-y*s,l.y+x*s+y*c];});}
export function warp(source,q,w,h,src){const [sx,sy,srw,srh]=src||[0,0,source.width,source.height],out=createSurface(w,h),x=out.getContext('2d'),dst=x.createImageData(w,h),a=source.getContext('2d').getImageData(0,0,source.width,source.height).data,inv=inverse(homography(q)),sw=source.width,sh=source.height,minX=Math.max(0,Math.floor(Math.min(...q.map(v=>v[0])))),maxX=Math.min(w,Math.ceil(Math.max(...q.map(v=>v[0])))),minY=Math.max(0,Math.floor(Math.min(...q.map(v=>v[1])))),maxY=Math.min(h,Math.ceil(Math.max(...q.map(v=>v[1]))));for(let yy=minY;yy<maxY;yy++)for(let xx=minX;xx<maxX;xx++){const [u,v]=project(inv,xx+.5,yy+.5);if(u<0||v<0||u>1||v>1)continue;const px=Math.max(sx,Math.min(sx+srw-1,u*srw+sx-.5)),py=Math.max(sy,Math.min(sy+srh-1,v*srh+sy-.5)),ix=Math.floor(px),iy=Math.floor(py),fx=px-ix,fy=py-iy,di=(yy*w+xx)*4;let alpha=0,rgb=[0,0,0];for(const [dx,dy,weight] of [[0,0,(1-fx)*(1-fy)],[1,0,fx*(1-fy)],[0,1,(1-fx)*fy],[1,1,fx*fy]]){const j=(Math.min(sh-1,iy+dy)*sw+Math.min(sw-1,ix+dx))*4,aa=a[j+3]*weight;alpha+=aa;for(let k=0;k<3;k++)rgb[k]+=a[j+k]*aa;}dst.data[di+3]=alpha;for(let k=0;k<3;k++)dst.data[di+k]=alpha?rgb[k]/alpha:0;}x.putImageData(dst,0,0);return out;}
